   157  otError Encoder::Encode(const uint8_t *aData, uint16_t aLength)
   158  {
   159      otError           error      = OT_ERROR_NONE;
   160      uint16_t          oldFcs     = mFcs;
   161      FrameWritePointer oldPointer = mWritePointer;
   162
   163      while (aLength--)
   164      {
   165          SuccessOrExit(error = Encode(*aData++));
   166      }
   167
   168  exit:
   169
   170      if (error != OT_ERROR_NONE)
   171      {
   172          mWritePointer = oldPointer;
   173          mFcs          = oldFcs;
   174      }
   175
   176      return error;
   177  }
