   179  otError Encoder::EndFrame(void)
   180  {
   181      otError           error      = OT_ERROR_NONE;
   182      FrameWritePointer oldPointer = mWritePointer;
   183      uint16_t          oldFcs     = mFcs;
   184      uint16_t          fcs        = mFcs;
   185
   186      fcs ^= 0xffff;
   187
   188      SuccessOrExit(error = Encode(fcs & 0xff));
   189      SuccessOrExit(error = Encode(fcs >> 8));
   190
   191      SuccessOrExit(error = mWritePointer.WriteByte(kFlagSequence));
   192
   193  exit:
   194
   195      if (error != OT_ERROR_NONE)
   196      {
   197          mWritePointer = oldPointer;
   198          mFcs          = oldFcs;
   199      }
   200
   201      return error;
   202  }
